#!/usr/bin/env bash
# Regression test for tests/check_ai_declarations.sh --staged. The pre-commit
# gate trusts this mode to see a commit still in the index, which the
# HEAD-scoped mode structurally cannot: that blind spot is exactly how an
# undeclared file once reached local/linux-master. Contract pinned here: staged
# adds are judged, unstaged and committed ones are not, vendored paths stay
# skipped, head mode still 125s without origin/master.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later

set -u

root=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  AI declaration self-test (not inside a git checkout)\n'
    exit 125
}
check=$root/tests/check_ai_declarations.sh
[ -f "$check" ] || {
    printf 'SKIP  AI declaration self-test (check absent on this branch)\n'
    exit 125
}

# Not a bare /tmp: MSYS child shells default TMP/TEMP to /tmp, and native
# git.exe then maps a /tmp argument to C:\tmp while bash sees %TEMP%.
if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -w "$USERPROFILE/AppData/Local/Temp")
else
    tmpbase="${TMPDIR:-/tmp}"
fi
tmp=$(mktemp -d "$tmpbase/pime-ai-decl-selftest.XXXXXX")
sandbox=$tmp/repo
mkdir -p "$sandbox"

cleanup() {
    rm -rf "$tmp"
}
trap cleanup EXIT

git -C "$sandbox" init -q >/dev/null || {
    printf 'SKIP  AI declaration self-test (git init failed)\n'
    exit 125
}

failures=0

# expect <want> <name> <mode>
expect() {
    want=$1; name=$2; modearg=$3
    out=$(cd "$sandbox" && bash "$check" "$modearg" 2>&1)
    got=$?
    if [ "$got" -ne "$want" ]; then
        printf 'FAIL  %s (want %s, got %s)\n%s\n' "$name" "$want" "$got" "$out"
        failures=$((failures + 1))
    else
        printf 'ok    %s\n' "$name"
    fi
}

# A staged file with no declaration must fail, and name the file.
printf 'x = 1\n' > "$sandbox/undeclared.py"
git -C "$sandbox" add undeclared.py
out=$(cd "$sandbox" && bash "$check" staged 2>&1)
got=$?
if [ "$got" -ne 1 ]; then
    printf 'FAIL  staged undeclared file fails (want 1, got %s)\n%s\n' "$got" "$out"
    failures=$((failures + 1))
elif ! printf '%s\n' "$out" | grep -q 'undeclared\.py'; then
    printf 'FAIL  staged failure names the offending file\n%s\n' "$out"
    failures=$((failures + 1))
else
    printf 'ok    staged undeclared file fails and is named\n'
fi

# head mode without origin/master is not applicable, not a failure: a fresh
# init has neither the ref nor a commit to compare against.
expect 125 'head mode skips without origin/master' head

# With a baseline commit and origin/master under it, head mode is applicable —
# and blind to the same staged add that staged mode just failed on. That
# asymmetry is the reason the staged mode exists; converging the two modes
# would reopen the blind spot silently.
git -C "$sandbox" -c user.name=selftest -c user.email=selftest@example.invalid \
    commit -qm 'selftest: baseline' -- undeclared.py
git -C "$sandbox" update-ref refs/remotes/origin/master HEAD
printf '# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.\n' > "$sandbox/undeclared.py"
printf '# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.\n' > "$sandbox/declared.py"
mkdir -p "$sandbox/python/python3"
printf 'x = 1\n' > "$sandbox/python/python3/vendored.py"
git -C "$sandbox" add declared.py undeclared.py
expect 0 'head mode ignores uncommitted adds' head

# Declared files pass; the vendored tree is skipped even when undeclared.
expect 0 'staged declared and vendored files pass' staged
git -C "$sandbox" add python/python3/vendored.py
expect 0 'staged vendored file stays skipped' staged

# An unstaged undeclared file is not the commit's business.
git -C "$sandbox" reset -q
printf 'x = 1\n' > "$sandbox/untracked.py"
git -C "$sandbox" add declared.py
expect 0 'unstaged undeclared file is ignored' staged

# Bad usage is a hard error, not a silent head scan.
expect 2 'unknown mode is rejected' bogus

printf '%d failed\n' "$failures"
[ "$failures" -eq 0 ]
